import pytest

from gateway import (
    Principal,
    Delegation,
    Resource,
    authorize
)

@pytest.fixture
def principal():

    return Principal(
        user_id="user_1",
        tenant_id="tenant_a",
        permissions=frozenset({
            "budget.read"
        })
    )

@pytest.fixture
def delegation():

    return Delegation(
        tenant_id="tenant_a",
        agent_id="finance_agent",
        permissions=frozenset({
            "budget.read"
        }),
        allowed_resources=frozenset({
            "department_101"
        })
    )

def test_authorized_read(
    principal,
    delegation
):

    resource = Resource(
        resource_id="department_101",
        tenant_id="tenant_a"
    )

    assert authorize(
        principal,
        delegation,
        resource,
        "budget.read"
    )

def test_cross_tenant_denied(
    principal,
    delegation
):

    resource = Resource(
        resource_id="department_101",
        tenant_id="tenant_b"
    )

    with pytest.raises(PermissionError):

        authorize(
            principal,
            delegation,
            resource,
            "budget.read"
        )

def test_write_denied(
    principal,
    delegation
):

    resource = Resource(
